CREATE PROCEDURE `BarChart_Events_ActivityOverTime`(
    IN serverId INT,
    IN daysBack INT
)
BEGIN
    SELECT JSON_OBJECT(
        'data',
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'day', t.dayStr,
                'count', t.cnt
            )
        ),
        'xAxisKey', 'day',
        'valueKeys', JSON_ARRAY('count')
    ) AS ChartDefinition
    FROM
    (
        SELECT
            d.dayStr,
            COALESCE(e.cnt, 0) AS cnt
        FROM
            (
                SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 0 DAY), '%Y-%m-%d') AS dayStr, CURDATE() AS dayDate
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 1 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 2 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 2 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 3 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 3 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 4 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 4 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 5 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 5 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 6 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 6 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 7 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 7 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 8 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 8 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 9 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 9 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 10 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 10 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 11 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 11 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 12 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 12 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 13 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 13 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 14 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 15 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 15 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 16 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 16 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 17 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 17 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 18 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 18 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 19 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 19 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 20 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 20 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 21 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 21 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 22 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 22 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 23 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 23 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 24 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 24 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 25 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 25 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 26 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 26 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 27 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 27 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 28 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 28 DAY)
                UNION ALL SELECT DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 29 DAY), '%Y-%m-%d'), DATE_SUB(CURDATE(), INTERVAL 29 DAY)
            ) d
        LEFT JOIN
            (
                SELECT
                    DATE_FORMAT(CreatedAt, '%Y-%m-%d') AS dayStr,
                    COUNT(*) AS cnt
                FROM events
                WHERE CreatedAt >= (CURDATE() - INTERVAL (daysBack - 1) DAY)
                  AND CreatedAt <  (CURDATE() + INTERVAL 1 DAY)
                  AND (serverId IS NULL OR ServerId = serverId)
                GROUP BY DATE_FORMAT(CreatedAt, '%Y-%m-%d')
            ) e
            ON e.dayStr = d.dayStr
        WHERE
            d.dayDate >= (CURDATE() - INTERVAL (daysBack - 1) DAY)
        ORDER BY
            d.dayDate
    ) t;
END
